values
  ((select id from w), 'recall', 'Fill in the missing word from Elijah''s response to Elisha''s request.', '2 Kings 2:10', 'He said, ''You have asked a hard thing. If you see me when I am taken from you, it will be so for you; but if not, it will not be so.''', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "He said, ''You have asked a ___ thing. If you see me when I am taken from you, it will be so for you...''", "answer": "hard"}', false, 1),
  ((select id from w), 'recall', 'Fill in the missing word from Elisha''s cry as Elijah was taken up.', '2 Kings 2:12', 'Elisha saw it, and he cried, ''My father, my father, the chariots of Israel and its horsemen!'' He saw him no more...', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "Elisha saw it, and he cried, ''My father, my father, the chariots of ___ and its horsemen!''", "answer": "Israel"}', false, 2),
  ((select id from w), 'recall', 'Fill in the missing word: what Elisha took up after Elijah was taken from him.', '2 Kings 2:13', 'He also took up Elijah''s mantle that fell from him, and went back and stood by the bank of the Jordan.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "He also took up Elijah''s ___ that fell from him, and went back and stood by the bank of the Jordan.", "answer": "mantle"}', false, 3),
  ((select id from w), 'recall', 'Fill in the missing word: which tribe alone was left, per 2 Kings 17:18.', '2 Kings 17:18', 'Therefore Yahweh was very angry with Israel, and removed them out of his sight. There was none left but the tribe of Judah only.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "...There was none left but the tribe of ___ only.", "answer": "Judah"}', false, 4),
  ((select id from w), 'recall', 'Fill in the missing word: what the children of Israel had done against Yahweh, per 2 Kings 17:7.', '2 Kings 17:7', 'It was so because the children of Israel had sinned against Yahweh their God, who brought them up out of the land of Egypt from under the hand of Pharaoh king of Egypt, and had feared other gods.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "It was so because the children of Israel had ___ against Yahweh their God, who brought them up out of the land of Egypt...", "answer": "sinned"}', false, 5),
  ((select id from w), 'recall', 'Fill in the missing word from Hezekiah''s prayer describing Yahweh''s throne.', '2 Kings 19:15', 'Yahweh, the God of Israel, who are enthroned above the cherubim, you are the God, even you alone, of all the kingdoms of the earth.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "Yahweh, the God of Israel, who are enthroned above the ___, you are the God, even you alone, of all the kingdoms of the earth.", "answer": "cherubim"}', false, 6),
  ((select id from w), 'recall', 'Fill in the missing word: what Hezekiah covered himself with when he heard the Assyrian threat.', '2 Kings 19:1', 'When King Hezekiah heard it, he tore his clothes, covered himself with sackcloth, and went into Yahweh''s house.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "When King Hezekiah heard it, he tore his clothes, covered himself with ___, and went into Yahweh''s house.", "answer": "sackcloth"}', false, 7),
  ((select id from w), 'recall', 'Fill in the missing word: what Hezekiah did with the letter before Yahweh.', '2 Kings 19:14', 'Hezekiah received the letter from the hand of the messengers and read it. Then Hezekiah went up to Yahweh''s house, and spread it before Yahweh.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "Hezekiah received the letter... and read it. Then Hezekiah went up to Yahweh''s house, and ___ it before Yahweh.", "answer": "spread"}', false, 8),
  ((select id from w), 'recall', 'Fill in the missing word describing Josiah''s heart, per Yahweh''s message through Huldah.', '2 Kings 22:19', 'because your heart was tender, and you humbled yourself before Yahweh when you heard what I spoke against this place and against its inhabitants, that they should become a desolation and a curse, and have torn your clothes and wept before me, I also have heard you,'' says Yahweh.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "...because your heart was ___, and you humbled yourself before Yahweh when you heard what I spoke against this place...", "answer": "tender"}', false, 9),
  ((select id from w), 'recall', 'Fill in the missing word from Josiah''s covenant renewal before Yahweh.', '2 Kings 23:3', 'The king stood by the pillar and made a covenant before Yahweh to walk after Yahweh and to keep his commandments, his testimonies, and his statutes with all his heart and all his soul, to confirm the words of this covenant that were written in this book; and all the people agreed to the covenant.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "...to walk after Yahweh and to keep his commandments, his testimonies, and his statutes with all his heart and all his ___...", "answer": "soul"}', false, 10),
  ((select id from w), 'recall', 'Fill in the missing word: in which year of Zedekiah''s reign the siege of Jerusalem began, per 2 Kings 25:1.', '2 Kings 25:1', 'In the ninth year of his reign, in the tenth month, in the tenth day of the month, Nebuchadnezzar king of Babylon came, he and all his army, against Jerusalem, and encamped against it; and they built forts against it around it.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "In the ___ year of his reign, in the tenth month, in the tenth day of the month, Nebuchadnezzar king of Babylon came... against Jerusalem.", "answer": "ninth"}', false, 11),
  ((select id from w), 'recall', 'Fill in the missing word: how long Jehoiachin ate bread before the king of Babylon, per 2 Kings 25:29.', '2 Kings 25:29', '...and changed his prison garments. Jehoiachin ate bread before him continually all the days of his life.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "...and changed his prison garments. Jehoiachin ate bread before him continually all the days of his ___.", "answer": "life"}', false, 12),
  ((select id from w), 'sequence', 'Put these five scenes of 2 Kings in the order they happen in the book.', '2 Kings 2:11; 17:5-6; 19:19; 22:8; 25:8-9', 'As they continued on and talked, behold, a chariot of fire and horses of fire separated them; and Elijah went up by a whirlwind into heaven.; The king of Assyria came up throughout all the land, went up to Samaria, and besieged it three years. In the ninth year of Hoshea the king of Assyria took Samaria and carried Israel away to Assyria.; Now therefore, Yahweh our God, save us, I beg you, out of his hand, that all the kingdoms of the earth may know that you, Yahweh, are God alone.; Hilkiah the high priest said to Shaphan the scribe, ''I have found the book of the law in Yahweh''s house.'' Hilkiah delivered the book to Shaphan, and he read it.; Nebuzaradan the captain of the guard, a servant of the king of Babylon, came to Jerusalem. He burned Yahweh''s house, the king''s house, and all the houses of Jerusalem.', 'WEB', 5, 'hard',
   '{"type": "sequence", "items": ["Elijah is taken up in a whirlwind and Elisha succeeds him as prophet (2 Kings 2)", "The northern kingdom, Israel, falls to Assyria after persistent idolatry (2 Kings 17)", "Hezekiah prays in the temple during Assyria''s siege of Jerusalem, and the siege ends (2 Kings 18-19)", "Josiah''s workers rediscover the book of the law, and Josiah renews the covenant (2 Kings 22-23)", "Babylon conquers Jerusalem, burns the temple, and carries the people into exile (2 Kings 25)"], "correct_order": [0, 1, 2, 3, 4]}', true, 13),
  ((select id from w), 'sequence', 'Given these three quotations from 2 Kings, place them in the order they occur and match each to its reference.', '2 Kings 2:9; 19:19; 22:8', '...''Ask what I shall do for you, before I am taken from you.'' Elisha said, ''Please let a double portion of your spirit be on me.''; Now therefore, Yahweh our God, save us, I beg you, out of his hand, that all the kingdoms of the earth may know that you, Yahweh, are God alone.; Hilkiah the high priest said to Shaphan the scribe, ''I have found the book of the law in Yahweh''s house.'' Hilkiah delivered the book to Shaphan, and he read it.', 'WEB', 5, 'hard',
   '{"type": "sequence", "items": ["2 Kings 2:9 — ...''Ask what I shall do for you, before I am taken from you.'' Elisha said, ''Please let a double portion of your spirit be on me.''", "2 Kings 19:19 — Now therefore, Yahweh our God, save us, I beg you, out of his hand, that all the kingdoms of the earth may know that you, Yahweh, are God alone.", "2 Kings 22:8 — Hilkiah the high priest said to Shaphan the scribe, ''I have found the book of the law in Yahweh''s house.'' Hilkiah delivered the book to Shaphan, and he read it."], "correct_order": [0, 1, 2]}', true, 14),
  ((select id from w), 'multiple_choice', 'According to 2 Kings 22:11, what did Josiah do when he heard the words of the book of the law?', '2 Kings 22:11', 'When the king had heard the words of the book of the law, he tore his clothes.', 'WEB', 5, 'hard',
   '{"type": "multiple_choice", "options": ["He tore his clothes", "He ignored the scroll", "He ordered a feast", "He rebuilt the temple immediately"], "correct_index": 0}', true, 15),
  ((select id from w), 'recall', 'Fill in the missing word: what Nebuzaradan did to the rest of the people left in the city, per 2 Kings 25:11.', '2 Kings 25:11', 'Nebuzaradan the captain of the guard carried away captive the rest of the people who were left in the city and those who had deserted to the king of Babylon—all the rest of the multitude.', 'WEB', 5, 'hard',
