-- ===================== 1 Chronicles — EASY tier (6 items: 4 regular + 2 boss) =====================
-- Deliberately thin — matches the medium tier's own deliberately-thin count per
-- docs/CANON_STRUCTURE.md §4. Not padded to resemble other books' tiers.

with w as (select id from public.world where book_slug = '1-chronicles')
insert into public.challenge (world_id, type, prompt, verse_ref, verse_text, translation, difficulty_rank, difficulty_tier, answer_key, is_boss_item, sort_order)
values
  ((select id from w), 'recall', 'Fill in the missing name: the third name in 1 Chronicles'' opening genealogy.', '1 Chronicles 1:1', 'Adam, Seth, Enosh,', 'WEB', 1, 'easy',
   '{"type": "recall", "template": "Adam, Seth, ___,", "answer": "Enosh"}', false, 1),
  ((select id from w), 'multiple_choice', 'According to 1 Chronicles 21:1, what was David moved to do?', '1 Chronicles 21:1', 'Satan stood up against Israel, and moved David to take a census of Israel.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Take a census of Israel", "Attack the Philistines", "Build an altar", "Flee to Ornan''s threshing floor"], "correct_index": 0}', false, 2),
  ((select id from w), 'multiple_choice', 'According to 1 Chronicles 21:26, how did Yahweh answer David after he built the altar and offered sacrifices?', '1 Chronicles 21:26', 'David built an altar to Yahweh there, and offered burnt offerings and peace offerings, and called on Yahweh; and he answered him from the sky by fire on the altar of burnt offering.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["By fire from the sky on the altar", "By a voice from heaven", "By sending rain", "By a vision in a dream"], "correct_index": 0}', false, 3),
  ((select id from w), 'multiple_choice', 'According to 1 Chronicles 28:20, what did David tell Solomon to be, in charging him to build the temple?', '1 Chronicles 28:20', 'Be strong and courageous, and do it. Don''t be afraid, nor be dismayed, for Yahweh God, even my God, is with you.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Strong and courageous", "Wealthy and wise", "Patient and humble", "Famous and powerful"], "correct_index": 0}', false, 4),
  ((select id from w), 'recall', 'Fill in the missing word: the stated reason Yahweh''s word gave David for why he could not build the temple.', '1 Chronicles 22:7-8', 'As for me, it was in my heart to build a house to the name of Yahweh my God. But Yahweh''s word came to me, saying, ''You have shed blood abundantly and have made great wars. You shall not build a house to my name, because you have shed much blood on the earth in my sight.''', 'WEB', 1, 'easy',
   '{"type": "recall", "template": "As for me, it was in my heart to build a house to the name of Yahweh my God. But Yahweh''s word came to me, saying, ''You have shed blood abundantly and have made great wars. You shall not build a house to my name, because you have shed much blood on the earth in my ___.''", "answer": "sight"}', true, 5),
  ((select id from w), 'multiple_choice', 'According to 1 Chronicles 22:14, what did David prepare in vast quantities for the temple Solomon would build?', '1 Chronicles 22:14', 'In my affliction I have prepared for Yahweh''s house one hundred thousand talents of gold, one million talents of silver, and bronze and iron without weight... I have also prepared timber and stone.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Gold, silver, bronze, iron, timber, and stone", "Gold and incense only", "Silver and cedar only", "Bronze and linen"], "correct_index": 0}', true, 6)
;

-- ===================== 1 Chronicles — HARD tier (6 items: 4 regular + 2 boss) =====================
-- Same thinness rationale as easy tier above.

with w as (select id from public.world where book_slug = '1-chronicles')
insert into public.challenge (world_id, type, prompt, verse_ref, verse_text, translation, difficulty_rank, difficulty_tier, answer_key, is_boss_item, sort_order)
values
  ((select id from w), 'recall', 'Fill in the missing name: the first name in 1 Chronicles'' opening genealogy.', '1 Chronicles 1:1', 'Adam, Seth, Enosh,', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "___, Seth, Enosh,", "answer": "Adam"}', false, 1),
  ((select id from w), 'recall', 'According to 1 Chronicles 21:18, fill in the missing name: on the threshing floor of ___ the Jebusite Yahweh''s angel commanded that an altar be raised.', '1 Chronicles 21:18', 'Yahweh''s angel commanded Gad to tell David that David should go up and raise an altar to Yahweh on the threshing floor of Ornan the Jebusite.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "Yahweh''s angel commanded Gad to tell David that David should go up and raise an altar to Yahweh on the threshing floor of ___ the Jebusite.", "answer": "Ornan"}', false, 2),
  ((select id from w), 'recall', 'Fill in the missing word, per 1 Chronicles 22:5: besides young, what did David say Solomon was?', '1 Chronicles 22:5', 'Solomon my son is young and tender, and the house that is to be built for Yahweh must be exceedingly magnificent... I will therefore make preparation for it.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "Solomon my son is young and ___, and the house that is to be built for Yahweh must be exceedingly magnificent... I will therefore make preparation for it.", "answer": "tender"}', false, 3),
  ((select id from w), 'recall', 'Fill in the missing word, per 1 Chronicles 29:14: David''s prayer says all things come from Yahweh, and ''we have given you of your ___.''', '1 Chronicles 29:14', 'But who am I, and what is my people, that we should be able to offer so willingly as this? For all things come from you, and we have given you of your own.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "But who am I, and what is my people, that we should be able to offer so willingly as this? For all things come from you, and we have given you of your ___.", "answer": "own"}', false, 4),
  ((select id from w), 'sequence', 'Given these four quotations from 1 Chronicles, place them in the order they occur and match each to its reference.', '1 Chronicles 22:7-8; 22:14; 28:9-10; 29:14', 'As for me, it was in my heart to build a house to the name of Yahweh my God. But Yahweh''s word came to me, saying, ''You have shed blood abundantly and have made great wars. You shall not build a house to my name, because you have shed much blood on the earth in my sight.''; In my affliction I have prepared for Yahweh''s house one hundred thousand talents of gold, one million talents of silver, and bronze and iron without weight... I have also prepared timber and stone.; You, Solomon my son, know the God of your father, and serve him with a perfect heart and with a willing mind... Take heed now, for Yahweh has chosen you to build a house for the sanctuary. Be strong, and do it.; But who am I, and what is my people, that we should be able to offer so willingly as this? For all things come from you, and we have given you of your own.', 'WEB', 5, 'hard',
   '{"type": "sequence", "items": ["1 Chronicles 22:7-8 — As for me, it was in my heart to build a house to the name of Yahweh my God. But Yahweh''s word came to me, saying, ''You have shed blood abundantly and have made great wars. You shall not build a house to my name, because you have shed much blood on the earth in my sight.''", "1 Chronicles 22:14 — In my affliction I have prepared for Yahweh''s house one hundred thousand talents of gold, one million talents of silver, and bronze and iron without weight... I have also prepared timber and stone.", "1 Chronicles 28:9-10 — You, Solomon my son, know the God of your father, and serve him with a perfect heart and with a willing mind... Take heed now, for Yahweh has chosen you to build a house for the sanctuary. Be strong, and do it.", "1 Chronicles 29:14 — But who am I, and what is my people, that we should be able to offer so willingly as this? For all things come from you, and we have given you of your own."], "correct_order": [0, 1, 2, 3]}', true, 5),
  ((select id from w), 'recall', 'Fill in the missing word, per 1 Chronicles 28:9-10: David charges Solomon to serve Yahweh with a perfect heart and a willing ___.', '1 Chronicles 28:9-10', 'You, Solomon my son, know the God of your father, and serve him with a perfect heart and with a willing mind... Take heed now, for Yahweh has chosen you to build a house for the sanctuary. Be strong, and do it.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "You, Solomon my son, know the God of your father, and serve him with a perfect heart and with a willing ___... Take heed now, for Yahweh has chosen you to build a house for the sanctuary. Be strong, and do it.", "answer": "mind"}', true, 6)
;

-- ===================== 2 Chronicles — EASY tier (12 items: 8 regular + 4 boss) =====================

with w as (select id from public.world where book_slug = '2-chronicles')
insert into public.challenge (world_id, type, prompt, verse_ref, verse_text, translation, difficulty_rank, difficulty_tier, answer_key, is_boss_item, sort_order)
values
  ((select id from w), 'multiple_choice', 'According to 2 Chronicles 5:13-14, what filled Yahweh''s house when the trumpeters and singers made one sound of praise?', '2 Chronicles 5:13-14', '...when the trumpeters and singers were as one, to make one sound to be heard in praising and thanking Yahweh... then the house was filled with a cloud, even Yahweh''s house, so that the priests could not stand to minister by reason of the cloud; for Yahweh''s glory filled God''s house.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["A cloud, filled with Yahweh''s glory", "Fire from heaven", "Total darkness", "A great earthquake"], "correct_index": 0}', false, 1),
  ((select id from w), 'multiple_choice', 'According to 2 Chronicles 7:1, what happened right after Solomon finished praying at the temple dedication?', '2 Chronicles 7:1', 'Now when Solomon had finished praying, fire came down from heaven and consumed the burnt offering and the sacrifices; and Yahweh''s glory filled the house.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Fire came down from heaven and consumed the sacrifice", "The ark disappeared from the temple", "An earthquake shook Jerusalem", "The priests began a new song"], "correct_index": 0}', false, 2),
  ((select id from w), 'multiple_choice', 'According to 2 Chronicles 29:1-2, what did Hezekiah do as king, following his father David''s example?', '2 Chronicles 29:1-2', 'Hezekiah began to reign when he was twenty-five years old, and he reigned twenty-nine years in Jerusalem... He did that which was right in Yahweh''s eyes, according to all that David his father had done.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["He did what was right in Yahweh''s eyes", "He built a new palace", "He raised a large army", "He made treaties with Egypt"], "correct_index": 0}', false, 3),
  ((select id from w), 'multiple_choice', 'According to 2 Chronicles 29:3, what did Hezekiah do in the first month of the first year of his reign?', '2 Chronicles 29:3', 'In the first year of his reign, in the first month, he opened the doors of Yahweh''s house and repaired them.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["He opened the doors of Yahweh''s house and repaired them", "He tore down the temple", "He appointed new priests", "He declared war on Assyria"], "correct_index": 0}', false, 4),
  ((select id from w), 'multiple_choice', 'According to 2 Chronicles 34:15, what did Hilkiah tell Shaphan the scribe he had found in Yahweh''s house?', '2 Chronicles 34:15', 'Hilkiah answered Shaphan the scribe, ''I have found the book of the law in Yahweh''s house.'' So Hilkiah delivered the book to Shaphan.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["The book of the law", "A hidden treasure", "A golden ark", "An ancient altar"], "correct_index": 0}', false, 5),
  ((select id from w), 'multiple_choice', 'According to 2 Chronicles 35:1, what did Josiah keep in Jerusalem?', '2 Chronicles 35:1', 'Josiah kept a Passover to Yahweh in Jerusalem. They killed the Passover on the fourteenth day of the first month.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["A Passover to Yahweh", "A coronation feast", "A harvest festival", "A day of mourning"], "correct_index": 0}', false, 6),
  ((select id from w), 'multiple_choice', 'According to 2 Chronicles 36:19-20, what happened to Jerusalem and its people?', '2 Chronicles 36:19-20', 'They burned God''s house, broke down the wall of Jerusalem, burned all its palaces with fire, and destroyed all of its valuable vessels. He carried those who had escaped from the sword away to Babylon...', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Burned God''s house and the city, and carried the survivors to Babylon", "Burned only the palace", "Made Jerusalem a Babylonian province without violence", "Rebuilt the temple"], "correct_index": 0}', false, 7),
  ((select id from w), 'multiple_choice', 'According to 2 Chronicles 36:23, what did Cyrus king of Persia''s decree permit?', '2 Chronicles 36:23', 'Cyrus king of Persia says, ''Yahweh, the God of heaven, has given all the kingdoms of the earth to me; and he has commanded me to build him a house in Jerusalem, which is in Judah. Whoever there is among you of all his people, Yahweh his God be with him, and let him go up.''', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Any of Yahweh''s people among them could go up to Jerusalem", "The exiles must remain in Babylon", "The temple would be rebuilt in Persia", "Judah''s kings would be restored to power"], "correct_index": 0}', false, 8),
  ((select id from w), 'multiple_choice', 'According to 2 Chronicles 36:22-23, which foreign king does the text say Yahweh ''stirred up'' to let the exiles return?', '2 Chronicles 36:22-23', 'In the first year of Cyrus king of Persia... Yahweh stirred up the spirit of Cyrus king of Persia, so that he made a proclamation throughout all his kingdom, and put it also in writing.; Cyrus king of Persia says, ''Yahweh, the God of heaven, has given all the kingdoms of the earth to me; and he has commanded me to build him a house in Jerusalem, which is in Judah. Whoever there is among you of all his people, Yahweh his God be with him, and let him go up.''', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Cyrus of Persia", "Nebuchadnezzar of Babylon", "Darius of Persia", "Sennacherib of Assyria"], "correct_index": 0}', true, 9),
  ((select id from w), 'sequence', 'Put these four scenes of 2 Chronicles in the order they happen in the book.', '2 Chronicles 7:1; 29:3; 35:1; 36:23', 'Now when Solomon had finished praying, fire came down from heaven and consumed the burnt offering and the sacrifices; and Yahweh''s glory filled the house.; In the first year of his reign, in the first month, he opened the doors of Yahweh''s house and repaired them.; Josiah kept a Passover to Yahweh in Jerusalem. They killed the Passover on the fourteenth day of the first month.; Cyrus king of Persia says, ''Yahweh, the God of heaven, has given all the kingdoms of the earth to me; and he has commanded me to build him a house in Jerusalem, which is in Judah. Whoever there is among you of all his people, Yahweh his God be with him, and let him go up.''', 'WEB', 1, 'easy',
   '{"type": "sequence", "items": ["Solomon''s Temple Dedication (2 Chronicles 7:1)", "Hezekiah''s Temple Cleansing (2 Chronicles 29:3)", "Josiah''s Passover (2 Chronicles 35:1)", "The Fall of Judah and Cyrus''s Decree (2 Chronicles 36:23)"], "correct_order": [0, 1, 2, 3]}', true, 10),
  ((select id from w), 'multiple_choice', 'According to 2 Chronicles 7:2, why could the priests not enter Yahweh''s house?', '2 Chronicles 7:2', 'The priests could not enter into Yahweh''s house, because Yahweh''s glory filled Yahweh''s house.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Because Yahweh''s glory filled the house", "Because the doors were sealed shut", "Because the ark hadn''t yet arrived", "Because Solomon forbade it"], "correct_index": 0}', true, 11),
  ((select id from w), 'multiple_choice', 'According to 2 Chronicles 29:5, what did Hezekiah command the Levites to do, besides sanctifying themselves?', '2 Chronicles 29:5', '...Listen to me, you Levites! Now sanctify yourselves, and sanctify the house of Yahweh, the God of your fathers, and carry the filthiness out of the holy place.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Sanctify the house of Yahweh and carry out its filthiness", "Rebuild the outer wall", "Appoint new judges", "Compose new psalms"], "correct_index": 0}', true, 12)
;

