with w as (select id from public.world where book_slug = '2-chronicles')
insert into public.challenge (world_id, type, prompt, verse_ref, verse_text, translation, difficulty_rank, difficulty_tier, answer_key, is_boss_item, sort_order)
values
  ((select id from w), 'recall', 'Fill in the missing word: what Solomon put the dedicated silver, gold, and vessels into, per 2 Chronicles 5:1.', '2 Chronicles 5:1', 'Thus all the work that Solomon did for Yahweh''s house was finished. Solomon brought in the things that David his father had dedicated, even the silver, the gold, and all the vessels, and put them in the treasuries of God''s house.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "...Solomon brought in the things that David his father had dedicated, even the silver, the gold, and all the vessels, and put them in the treasuries of God''s ___.", "answer": "house"}', false, 1),
  ((select id from w), 'recall', 'Fill in the missing word: where the priests placed the ark, per 2 Chronicles 5:7.', '2 Chronicles 5:7', 'The priests brought in the ark of Yahweh''s covenant to its place, into the inner sanctuary of the house, to the most holy place, even under the wings of the cherubim.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "The priests brought in the ark of Yahweh''s covenant to its place, into the inner sanctuary of the house, to the most holy place, even under the wings of the ___.", "answer": "cherubim"}', false, 2),
  ((select id from w), 'recall', 'Fill in the missing word: what the priests told Hezekiah they had done to Yahweh''s house, per 2 Chronicles 29:18.', '2 Chronicles 29:18', '...We have cleansed all Yahweh''s house, including the altar of burnt offering with all its vessels, and the table of show bread with all its vessels.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "...We have ___ all Yahweh''s house, including the altar of burnt offering with all its vessels, and the table of show bread with all its vessels.", "answer": "cleansed"}', false, 3),
  ((select id from w), 'recall', 'Fill in the missing word from Hezekiah''s stated intent to make a covenant, per 2 Chronicles 29:10.', '2 Chronicles 29:10', 'Now it is in my heart to make a covenant with Yahweh, the God of Israel, that his fierce anger may turn away from us.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "Now it is in my heart to make a covenant with Yahweh, the God of Israel, that his fierce ___ may turn away from us.", "answer": "anger"}', false, 4),
  ((select id from w), 'recall', 'Fill in the missing word: what Josiah tore when he heard the words of the law, per 2 Chronicles 34:19.', '2 Chronicles 34:19', 'When the king had heard the words of the law, he tore his clothes.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "When the king had heard the words of the law, he tore his ___.", "answer": "clothes"}', false, 5),
  ((select id from w), 'recall', 'Fill in the missing word from Josiah''s covenant renewal, per 2 Chronicles 34:31.', '2 Chronicles 34:31', 'The king stood in his place and made a covenant before Yahweh, to walk after Yahweh, and to keep his commandments, his testimonies, and his statutes with all his heart and with all his soul, to perform the words of the covenant that were written in this book.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "...to walk after Yahweh, and to keep his commandments, his testimonies, and his statutes with all his heart and with all his ___, to perform the words of the covenant that were written in this book.", "answer": "soul"}', false, 6),
  ((select id from w), 'recall', 'Fill in the missing word: how many years the land''s desolation fulfilled, per 2 Chronicles 36:21.', '2 Chronicles 36:21', '...to fulfill Yahweh''s word by Jeremiah''s mouth, until the land had enjoyed its Sabbaths. As long as it lay desolate, it kept Sabbath, to fulfill seventy years.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "...As long as it lay desolate, it kept Sabbath, to fulfill seventy ___.", "answer": "years"}', false, 7),
  ((select id from w), 'recall', 'Fill in the missing word from Cyrus''s decree, per 2 Chronicles 36:23.', '2 Chronicles 36:23', 'Cyrus king of Persia says, ''Yahweh, the God of heaven, has given all the kingdoms of the earth to me; and he has commanded me to build him a house in Jerusalem, which is in Judah... let him go up.''', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "Cyrus king of Persia says, ''Yahweh, the God of ___, has given all the kingdoms of the earth to me; and he has commanded me to build him a house in Jerusalem, which is in Judah... let him go up.''", "answer": "heaven"}', false, 8),
  ((select id from w), 'recall', 'Fill in the missing word from the people''s song of thanks when the fire fell on Solomon''s altar.', '2 Chronicles 7:3', 'All the children of Israel looked on, when the fire came down, and Yahweh''s glory was on the house. They bowed themselves with their faces to the ground on the pavement, worshiped, and gave thanks to Yahweh, saying, ''For he is good, for his loving kindness endures forever!''', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "All the children of Israel looked on, when the fire came down, and Yahweh''s glory was on the house. They bowed themselves with their faces to the ground on the pavement, worshiped, and gave thanks to Yahweh, saying, ''For he is good, for his loving kindness endures ___!''", "answer": "forever"}', true, 9),
  ((select id from w), 'recall', 'Fill in the missing word: what the text says had not been kept like this since the days of Samuel the prophet.', '2 Chronicles 35:18', 'There was no Passover like that kept in Israel from the days of Samuel the prophet, nor did any of the kings of Israel keep such a Passover as Josiah kept...', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "There was no ___ like that kept in Israel from the days of Samuel the prophet, nor did any of the kings of Israel keep such a Passover as Josiah kept...", "answer": "Passover"}', true, 10),
  ((select id from w), 'recall', 'Fill in the missing word: what Hezekiah told the Levites to carry out of the holy place, per 2 Chronicles 29:5.', '2 Chronicles 29:5', '...Listen to me, you Levites! Now sanctify yourselves, and sanctify the house of Yahweh, the God of your fathers, and carry the filthiness out of the holy place.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "...Listen to me, you Levites! Now sanctify yourselves, and sanctify the house of Yahweh, the God of your fathers, and carry the ___ out of the holy place.", "answer": "filthiness"}', true, 11),
  ((select id from w), 'recall', 'Fill in the missing word: what the text says there was no more of, once Yahweh''s wrath arose against his people, per 2 Chronicles 36:16.', '2 Chronicles 36:16', '...but they mocked the messengers of God, despised his words, and scoffed at his prophets, until Yahweh''s wrath arose against his people, until there was no remedy.', 'WEB', 5, 'hard',
   '{"type": "recall", "template": "...until Yahweh''s wrath arose against his people, until there was no ___.", "answer": "remedy"}', true, 12)
